/**
 * PLACEHOLDER ART — generated by code, to be replaced by the final graphics.
 * Every texture here is original and drawn pixel by pixel on a canvas, then
 * displayed without smoothing (nearest filtering) for the pixel-art look.
 */
import { CanvasTexture, NearestFilter, RepeatWrapping, SRGBColorSpace } from 'three';
import { createSeededRandom, pickRandom } from '../../shared/simulation/random';

/** Pixel density shared by all placeholder art: texture pixels per world unit. */
export const PIXELS_PER_UNIT = 24;

type Painter = (ctx: CanvasRenderingContext2D) => void;

/** Creates a crisp, repeatable pixel-art texture from a canvas painter. */
export function createPixelTexture(width: number, height: number, paint: Painter): CanvasTexture {
  const canvas = document.createElement('canvas');
  canvas.width = width;
  canvas.height = height;
  const ctx = canvas.getContext('2d');
  if (!ctx) throw new Error('2D canvas is not available');
  ctx.imageSmoothingEnabled = false;
  paint(ctx);

  const texture = new CanvasTexture(canvas);
  texture.magFilter = NearestFilter;
  texture.minFilter = NearestFilter;
  texture.generateMipmaps = false;
  texture.colorSpace = SRGBColorSpace;
  texture.wrapS = RepeatWrapping;
  texture.wrapT = RepeatWrapping;
  return texture;
}

/**
 * Draws a one-pixel dark outline around everything already painted, the
 * classic way to make a sprite readable on any background.
 */
export function outlineSprite(ctx: CanvasRenderingContext2D, color: [number, number, number]): void {
  const { width, height } = ctx.canvas;
  const image = ctx.getImageData(0, 0, width, height);
  const source = new Uint8ClampedArray(image.data);
  const isSolid = (x: number, y: number) =>
    x >= 0 && x < width && y >= 0 && y < height && (source[(y * width + x) * 4 + 3] ?? 0) > 0;

  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      if (isSolid(x, y)) continue;
      if (isSolid(x - 1, y) || isSolid(x + 1, y) || isSolid(x, y - 1) || isSolid(x, y + 1)) {
        const offset = (y * width + x) * 4;
        image.data[offset] = color[0];
        image.data[offset + 1] = color[1];
        image.data[offset + 2] = color[2];
        image.data[offset + 3] = 255;
      }
    }
  }
  ctx.putImageData(image, 0, 0);
}

/** Fills an ellipse pixel by pixel (no anti-aliasing, unlike canvas arcs). */
function fillPixelEllipse(
  ctx: CanvasRenderingContext2D,
  centerX: number,
  centerY: number,
  radiusX: number,
  radiusY: number,
): void {
  for (let y = Math.floor(centerY - radiusY); y <= Math.ceil(centerY + radiusY); y++) {
    for (let x = Math.floor(centerX - radiusX); x <= Math.ceil(centerX + radiusX); x++) {
      const dx = (x + 0.5 - centerX) / radiusX;
      const dy = (y + 0.5 - centerY) / radiusY;
      if (dx * dx + dy * dy <= 1) ctx.fillRect(x, y, 1, 1);
    }
  }
}

export const PLACEHOLDER_PLANT_SIZE = { width: 20, height: 30 };

/** Potted plant sprite (small decorative objects are 2D sprites in the scene). */
export function createPlaceholderPlantTexture(): CanvasTexture {
  const { width, height } = PLACEHOLDER_PLANT_SIZE;
  return createPixelTexture(width, height, (ctx) => {
    // Leaves, from the darkest at the back to the lightest in front
    const leaves: Array<[string, number, number, number, number]> = [
      ['#2f6b3c', 10, 9, 6.5, 7.5],
      ['#2f6b3c', 5.5, 13, 3.5, 5],
      ['#2f6b3c', 14.5, 13, 3.5, 5],
      ['#3f8a4b', 8, 8, 3.5, 5],
      ['#3f8a4b', 13, 10, 3, 4.5],
      ['#58a85c', 9, 6, 1.6, 2.6],
      ['#58a85c', 13.5, 8.5, 1.3, 2],
      ['#58a85c', 6, 12, 1.2, 2],
    ];
    for (const [color, x, y, radiusX, radiusY] of leaves) {
      ctx.fillStyle = color;
      fillPixelEllipse(ctx, x, y, radiusX, radiusY);
    }
    // Terracotta pot
    ctx.fillStyle = '#b5633c';
    ctx.fillRect(5, 19, 10, 2);
    ctx.fillRect(6, 21, 8, 7);
    ctx.fillRect(7, 28, 6, 1);
    ctx.fillStyle = '#cf7d50';
    ctx.fillRect(6, 19, 3, 1);
    ctx.fillRect(7, 21, 1, 6);
    ctx.fillStyle = '#8e4a2b';
    ctx.fillRect(12, 21, 2, 7);
    outlineSprite(ctx, [38, 26, 34]);
  });
}

/** Rug with a border and a diamond pattern; sized in world units. */
export function createPlaceholderRugTexture(widthInUnits: number, depthInUnits: number): CanvasTexture {
  const width = widthInUnits * PIXELS_PER_UNIT;
  const height = depthInUnits * PIXELS_PER_UNIT;
  return createPixelTexture(width, height, (ctx) => {
    ctx.fillStyle = '#7d3340';
    ctx.fillRect(0, 0, width, height);
    ctx.fillStyle = '#e6d3a8';
    ctx.fillRect(3, 3, width - 6, height - 6);
    ctx.fillStyle = '#8f3d4a';
    ctx.fillRect(5, 5, width - 10, height - 10);
    // Diamond motifs along the centre line
    ctx.fillStyle = '#e6d3a8';
    const centerY = height / 2;
    for (let centerX = PIXELS_PER_UNIT / 2; centerX < width; centerX += PIXELS_PER_UNIT) {
      for (let offset = -6; offset <= 6; offset++) {
        const half = 6 - Math.abs(offset);
        ctx.fillRect(centerX - half, centerY + offset, half * 2, 1);
      }
    }
    ctx.fillStyle = '#7d3340';
    for (let centerX = PIXELS_PER_UNIT / 2; centerX < width; centerX += PIXELS_PER_UNIT) {
      ctx.fillRect(centerX - 2, centerY - 1, 4, 2);
    }
  });
}

const WOOD_SHADES: readonly [string, ...string[]] = ['#b98a5a', '#b28152', '#c1925f', '#ab7b4e'];
const WOOD_SEAM = '#8a6240';
const WOOD_GRAIN = '#a37548';

/**
 * Wooden floor. One tile covers 2 × 2 cells so the plank pattern does not
 * repeat on every single cell.
 */
export function createPlaceholderFloorTexture(cols: number, rows: number): CanvasTexture {
  const tile = PIXELS_PER_UNIT * 2;
  const plankHeight = 6;

  const texture = createPixelTexture(tile, tile, (ctx) => {
    const random = createSeededRandom(11);
    for (let line = 0; line < tile / plankHeight; line++) {
      const y = line * plankHeight;
      // One long plank per line, as wide as the tile so it wraps cleanly;
      // only the position of its end joint changes from line to line.
      ctx.fillStyle = pickRandom(WOOD_SHADES, random);
      ctx.fillRect(0, y, tile, plankHeight);
      ctx.fillStyle = WOOD_SEAM;
      ctx.fillRect(Math.floor(random() * (tile / 4)) * 4, y, 1, plankHeight);
      ctx.fillRect(0, y + plankHeight - 1, tile, 1);
    }
    ctx.fillStyle = WOOD_GRAIN;
    for (let speck = 0; speck < 40; speck++) {
      const line = Math.floor(random() * (tile / plankHeight));
      const x = Math.floor(random() * (tile - 3));
      const y = line * plankHeight + 1 + Math.floor(random() * (plankHeight - 3));
      ctx.fillRect(x, y, 2 + Math.floor(random() * 2), 1);
    }
  });
  texture.repeat.set(cols / 2, rows / 2);
  return texture;
}

/**
 * Wall panel: plaster on top, wooden wainscot and baseboard at the bottom.
 * The texture is one unit wide and exactly as tall as the wall.
 */
export function createPlaceholderWallTexture(lengthInUnits: number, wallHeight: number): CanvasTexture {
  const width = PIXELS_PER_UNIT;
  const height = Math.round(wallHeight * PIXELS_PER_UNIT);
  const wainscotTop = height - 20;

  const texture = createPixelTexture(width, height, (ctx) => {
    const random = createSeededRandom(23);
    // Plaster
    ctx.fillStyle = '#d9cfb8';
    ctx.fillRect(0, 0, width, wainscotTop);
    ctx.fillStyle = '#cfc4ab';
    for (let speck = 0; speck < 26; speck++) {
      ctx.fillRect(Math.floor(random() * width), Math.floor(random() * wainscotTop), 1, 1);
    }
    ctx.fillStyle = '#b9ad93';
    ctx.fillRect(0, 0, width, 2);
    // Chair rail
    ctx.fillStyle = '#5f4330';
    ctx.fillRect(0, wainscotTop, width, 2);
    // Wainscot with two grooved boards per unit
    ctx.fillStyle = '#8a6243';
    ctx.fillRect(0, wainscotTop + 2, width, 15);
    for (const x of [0, width / 2]) {
      ctx.fillStyle = '#6f4d34';
      ctx.fillRect(x, wainscotTop + 2, 1, 15);
      ctx.fillStyle = '#9c7250';
      ctx.fillRect(x + 1, wainscotTop + 2, 1, 15);
    }
    // Baseboard
    ctx.fillStyle = '#4d3423';
    ctx.fillRect(0, height - 3, width, 3);
  });
  texture.repeat.set(lengthInUnits, 1);
  return texture;
}
